function validate([a, b, c]) {
  for (const value of [a, b, c]) {
    if (!Number.isInteger(value) || value < 1 || value > 100) return 'Each position is a whole number from 1 to 100.';
  }
  if (a === b || b === c || a === c) return 'The three positions must be different.';
  return null;
}

