function numMovesStones(a, b, c) {
  // Exhaustive game search. Only the distances between neighbouring stones matter, so a state is
  // (left, right) with the stones at 0, left and left + right; every legal move is tried and cached.
  const memo = new Map();
  const solve = (left, right) => {
    if (left === 1 && right === 1) return [0, 0];
    const key = left * 1000 + right;
    if (memo.has(key)) return memo.get(key);
    let low = Infinity, high = -Infinity;
    const consider = (p, q) => {
      const [childLow, childHigh] = solve(p, q);
      low = Math.min(low, childLow + 1);
      high = Math.max(high, childHigh + 1);
    };
    const span = left + right;
    for (let k = 1; k < span; k++) {
      if (k === left) continue;
      // Move the stone at 0 to k.
      if (k < left) consider(left - k, right); else consider(k - left, span - k);
      // Move the stone at span to k.
      if (k < left) consider(k, left - k); else consider(left, k - left);
    }
    const result = [low, high];
    memo.set(key, result);
    return result;
  };
  const [x, y, z] = [a, b, c].sort((u, v) => u - v);
  return solve(y - x, z - y);
}

