function generate(rand, size) {
  const limit = size === 'large' ? 100 : 12;
  const values = [];
  while (values.length < 3) {
    const value = 1 + Math.floor(rand() * limit);
    if (!values.includes(value)) values.push(value);
  }
  return values;
}
